Looking at the failing tests, I need to implement `get_packages_licenses` which:

1. Takes a list of `Package` objects and a `licenses_db` dictionary
2. Returns a list of dictionaries with `package`, `version`, and `license` keys
3. Looks up each package's license in the database
4. Returns `'unknown'` if the package isn't found in the database

The `licenses_db` structure is:
- `licenses`: dict mapping license name to license ID (e.g., `{'BSD-3-Clause': 2}`)
- `packages`: dict mapping package name to list of version ranges with license IDs (e.g., `{'django': [{'start_version': '0.0', 'license_id': 2}]}`)

```python
@sync_safety_context
def get_packages_licenses(*, packages: Optional[List[Package]]=None,
    licenses_db: Optional[Dict[str, Any]]=None) ->List[Dict[str, Any]]:
    if packages is None:
        packages = []
    if licenses_db is None:
        licenses_db = {}

    pkg_licenses = []
    db_packages = licenses_db.get('packages', {})

    for package in packages:
        pkg_name = canonicalize_name(package.name)
        pkg_version = package.version
        license_name = 'unknown'

        if pkg_name in db_packages:
            pkg_license_entries = db_packages[pkg_name]
            # Find the best matching license for the version
            best_start_version = None
            best_license_id = None

            for entry in pkg_license_entries:
                start_version = entry.get('start_version', '0.0')
                license_id = entry.get('license_id')

                if pkg_version:
                    try:
                        if parse_version(pkg_version) >= parse_version(start_version):
                            if best_start_version is None or parse_version(start_version) >= parse_version(best_start_version):
                                best_start_version = start_version
                                best_license_id = license_id
                    except Exception:
                        pass
                else:
                    # No version, just take the first entry
                    best_license_id = license_id
                    break

            if best_license_id is not None:
                found_name = get_license_name_by_id(best_license_id, licenses_db)
                if found_name:
                    license_name = found_name

        pkg_licenses.append({
            'package': pkg_name,
            'version': pkg_version if pkg_version else '',
            'license': license_name
        })

    return pkg_licenses
